import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { decodePng } from '../../../tools/design-gen/lib/raster.mjs';

// The app icon, generated by tools/design-gen (design/README.md, "App icon"): what the
// manifest, the page and the offline shell name must exist, at the size they say.
const pwa = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (f) => readFileSync(path.join(pwa, f), 'utf8');

function pngSize(file) {
  const b = readFileSync(path.join(pwa, file));
  assert.equal(b.toString('latin1', 1, 4), 'PNG', `${file} is a PNG`);
  return `${b.readUInt32BE(16)}x${b.readUInt32BE(20)}`;
}

test('the manifest names an any, a maskable and a monochrome PNG icon at 192 and 512, each a file of the size it states', () => {
  const { icons } = JSON.parse(read('manifest.webmanifest'));
  for (const purpose of ['any', 'maskable', 'monochrome']) {
    for (const sizes of ['192x192', '512x512']) {
      assert.ok(icons.some((i) => i.purpose === purpose && i.sizes === sizes && i.type === 'image/png'), `${purpose} ${sizes}`);
    }
  }
  for (const i of icons) {
    assert.ok(existsSync(path.join(pwa, i.src)), i.src);
    if (i.type === 'image/png') { assert.equal(pngSize(i.src), i.sizes, i.src); }
  }
});

test('the page\'s favicon is the SVG tile and its touch icon a 180 px PNG', () => {
  const html = read('index.html');
  assert.match(html, /<link rel="icon" href="icon\.svg" type="image\/svg\+xml">/);
  assert.match(read('icon.svg'), /Generated by tools\/design-gen/);
  const touch = /<link rel="apple-touch-icon" href="([^"]+)" sizes="180x180">/.exec(html);
  assert.ok(touch, 'an apple-touch-icon with its size');
  assert.equal(pngSize(touch[1]), '180x180');
});

test('the offline shell holds every icon the manifest, the page and notifications name', () => {
  const sw = read('sw.js');
  const shell = new Set([...sw.matchAll(/'\.\/([^']+)'/g)].map((m) => m[1]));
  const named = [
    ...JSON.parse(read('manifest.webmanifest')).icons.map((i) => i.src),
    ...[...read('index.html').matchAll(/<link rel="(?:icon|apple-touch-icon)" href="([^"]+)"/g)].map((m) => m[1]),
    /icon: '([^']+)'/.exec(sw)[1],
    /badge: '([^']+)'/.exec(sw)[1],
  ];
  assert.deepEqual(named.filter((f) => !shell.has(f)), []);
});

test('the monochrome icons and the notification badge are the mark alone, white on transparency, as Android draws them by their alpha', () => {
  for (const file of ['icons/monochrome-192.png', 'icons/monochrome-512.png', 'icons/badge-96.png']) {
    const { width, pixels } = decodePng(readFileSync(path.join(pwa, file)));
    const alpha = (x, y) => pixels[(y * width + x) * 4 + 3];
    assert.equal(alpha(0, 0), 0, `${file}: no plate in the corner`);
    let marked = 0;
    for (let i = 0; i < pixels.length; i += 4) {
      if (pixels[i + 3] === 0) { continue; }
      marked++;
      assert.deepEqual([...pixels.subarray(i, i + 3)], [255, 255, 255], `${file}: the mark is white`);
    }
    assert.ok(marked > width, `${file} draws the mark`);
  }
});
